NM={'R1':'Okuma 1 · Çoktan seçmeli boşluk','R2':'Okuma 2 · Açık boşluk','R3':'Okuma 3 · Kelime türetme','R4':'Okuma 4 · Cümle dönüştürme','R5':'Okuma 5 · Uzun metin','R6':'Okuma 6 · Cümle yerleştirme','R7':'Okuma 7 · Çoklu eşleştirme',
 'L1':'Dinleme 1 · Kısa kayıtlar','L2':'Dinleme 2 · Cümle tamamlama','L3':'Dinleme 3 · Çoklu eşleştirme','L4':'Dinleme 4 · Röportaj'}
def P(k,**o):
    d={'k':k,'nm':NM[k],'ti':('Reading and Use of English' if k[0]=='R' else 'Listening')+' Part '+k[1],'ins':INS[k]};d.update(o);return d
def q(qq,o,a,tg,e,**k):
    d={'q':qq,'o':o,'a':a,'tg':tg,'e':e};d.update(k);return d
def lq(i,sc,qq,o,a,tg,e):return {'id':i,'sc':sc,'q':qq,'o':o,'a':a,'tg':tg,'e':e}
def kw(s1,key,s2,a,tg,e):return {'s1':s1,'key':key,'s2':s2,'a':a,'tg':tg,'e':e}
WP=lambda *a:[(x,y) for x,y in a]

