 o=[(['win','gain','earn','reach'],1,['collocation']),(['levels','grades','marks','amounts'],0,['collocation']),(['catch','acquire','reach','achieve'],1,['vocab']),(['put','give','place','set'],2,['collocation']),(['Therefore','Moreover','Otherwise','However'],3,['linkers-contrast-purpose']),(['joins','equals','matches','agrees'],2,['vocab']),(['on','with','at','to'],1,['collocation']),(['take on','take up','take over','take in'],0,['vocab'])],
